BEGIN TRANSACTION;
CREATE TABLE activity(id INTEGER PRIMARY KEY, project_id INTEGER REFERENCES projects(id), occurred TEXT, description TEXT);
CREATE TABLE bid_items(id INTEGER PRIMARY KEY,bid_id INTEGER NOT NULL REFERENCES bids(id),title TEXT NOT NULL,item_type TEXT DEFAULT 'Base',building_area TEXT DEFAULT '',specification TEXT DEFAULT '',material TEXT DEFAULT '',quantity_basis TEXT DEFAULT 'Manual',quantity TEXT DEFAULT '1',length TEXT DEFAULT '0',width TEXT DEFAULT '0',unit TEXT DEFAULT 'each',waste_percent TEXT DEFAULT '0',material_unit_cost TEXT DEFAULT '0',labor_hours_per_unit TEXT DEFAULT '0',labor_rate TEXT DEFAULT '0',equipment_unit_cost TEXT DEFAULT '0',subcontract_unit_cost TEXT DEFAULT '0',other_cost TEXT DEFAULT '0',included INTEGER DEFAULT 1,notes TEXT DEFAULT '');
CREATE TABLE bid_packages(id INTEGER PRIMARY KEY,project_id INTEGER NOT NULL REFERENCES projects(id),title TEXT NOT NULL,discipline TEXT DEFAULT 'General',building_area TEXT DEFAULT '',bid_type TEXT DEFAULT 'Lump Sum',scope TEXT DEFAULT '',deadline TEXT DEFAULT '',status TEXT DEFAULT 'Draft',notes TEXT DEFAULT '');
CREATE TABLE bids(id INTEGER PRIMARY KEY,package_id INTEGER NOT NULL REFERENCES bid_packages(id),title TEXT NOT NULL,contact_id INTEGER REFERENCES contacts(id),currency TEXT DEFAULT 'USD',status TEXT DEFAULT 'Draft',received TEXT DEFAULT '',valid_until TEXT DEFAULT '',tax_percent TEXT DEFAULT '0',markup_percent TEXT DEFAULT '0',contingency_percent TEXT DEFAULT '0',discount TEXT DEFAULT '0',exclusions TEXT DEFAULT '',schedule_notes TEXT DEFAULT '',notes TEXT DEFAULT '');
CREATE TABLE communications(id INTEGER PRIMARY KEY, project_id INTEGER NOT NULL REFERENCES projects(id), contact_id INTEGER REFERENCES contacts(id), occurred TEXT NOT NULL, summary TEXT NOT NULL, follow_up TEXT DEFAULT '', status TEXT DEFAULT 'Open');
CREATE TABLE contacts(id INTEGER PRIMARY KEY, name TEXT NOT NULL, role TEXT DEFAULT '', company TEXT DEFAULT '', email TEXT DEFAULT '', phone TEXT DEFAULT '', notes TEXT DEFAULT '', discipline TEXT DEFAULT 'General');
CREATE TABLE documents(id INTEGER PRIMARY KEY, project_id INTEGER NOT NULL REFERENCES projects(id), title TEXT NOT NULL, category TEXT DEFAULT 'Architectural Plans', discipline TEXT DEFAULT 'General', sheet_number TEXT DEFAULT '', drawing_type TEXT DEFAULT 'Plan Set', building_area TEXT DEFAULT '', scale TEXT DEFAULT '', designer_id INTEGER REFERENCES contacts(id), issue_purpose TEXT DEFAULT '');
CREATE TABLE meetings(id INTEGER PRIMARY KEY,project_id INTEGER NOT NULL REFERENCES projects(id),title TEXT NOT NULL,meeting_type TEXT DEFAULT 'Coordination',meeting_date TEXT NOT NULL,start_time TEXT DEFAULT '',location TEXT DEFAULT '',contact_id INTEGER REFERENCES contacts(id),attendees TEXT DEFAULT '',agenda TEXT DEFAULT '',minutes TEXT DEFAULT '',decisions TEXT DEFAULT '',status TEXT DEFAULT 'Scheduled');
CREATE TABLE milestones(id INTEGER PRIMARY KEY, project_id INTEGER NOT NULL REFERENCES projects(id), title TEXT NOT NULL, phase TEXT DEFAULT '', deadline TEXT DEFAULT '', status TEXT DEFAULT 'Planned');
CREATE TABLE project_contacts(project_id INTEGER REFERENCES projects(id), contact_id INTEGER REFERENCES contacts(id), PRIMARY KEY(project_id,contact_id));
CREATE TABLE projects(id INTEGER PRIMARY KEY, name TEXT NOT NULL, address TEXT DEFAULT '', owner TEXT DEFAULT '', description TEXT DEFAULT '', phase TEXT DEFAULT 'Planning', status TEXT DEFAULT 'Active', archived INTEGER DEFAULT 0, updated TEXT);
CREATE TABLE registers(id INTEGER PRIMARY KEY,project_id INTEGER NOT NULL REFERENCES projects(id),title TEXT NOT NULL,record_type TEXT DEFAULT 'RFI',reference TEXT DEFAULT '',discipline TEXT DEFAULT 'General',building_area TEXT DEFAULT '',contact_id INTEGER REFERENCES contacts(id),status TEXT DEFAULT 'Open',submitted TEXT DEFAULT '',deadline TEXT DEFAULT '',response TEXT DEFAULT '',notes TEXT DEFAULT '');
CREATE TABLE tasks(id INTEGER PRIMARY KEY, project_id INTEGER NOT NULL REFERENCES projects(id), title TEXT NOT NULL, deadline TEXT DEFAULT '', priority TEXT DEFAULT 'Normal', contact_id INTEGER REFERENCES contacts(id), status TEXT DEFAULT 'Not Started', notes TEXT DEFAULT '', discipline TEXT DEFAULT 'General', building_area TEXT DEFAULT '', meeting_id INTEGER REFERENCES meetings(id));
CREATE TABLE versions(id INTEGER PRIMARY KEY, document_id INTEGER NOT NULL REFERENCES documents(id), revision TEXT NOT NULL, submitted TEXT DEFAULT '', status TEXT DEFAULT 'Draft', requirements TEXT DEFAULT '', file_path TEXT DEFAULT '', resubmission INTEGER DEFAULT 0, created TEXT, UNIQUE(document_id,revision));
CREATE TABLE work_packages(id INTEGER PRIMARY KEY,project_id INTEGER NOT NULL REFERENCES projects(id),title TEXT NOT NULL,discipline TEXT DEFAULT 'General',building_area TEXT DEFAULT '',contact_id INTEGER REFERENCES contacts(id),status TEXT DEFAULT 'Not Started',deadline TEXT DEFAULT '',scope TEXT DEFAULT '',requirements TEXT DEFAULT '',notes TEXT DEFAULT '');
CREATE UNIQUE INDEX one_award_per_package ON bids(package_id) WHERE status='Awarded';
CREATE INDEX work_project ON work_packages(project_id);
CREATE INDEX meetings_project ON meetings(project_id);
CREATE INDEX register_project ON registers(project_id);
CREATE INDEX bid_package_project ON bid_packages(project_id);
CREATE INDEX bids_package ON bids(package_id);
CREATE INDEX items_bid ON bid_items(bid_id);
COMMIT;
PRAGMA user_version=2;
